import{_ as u,a8 as l,o as d,c as h,ah as _,a as e,a3 as t,K as o,L as i}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const P=JSON.parse('{"title":"帮老适 AI 转型框架 v2 迭代决策（2026-09-12）","description":"","frontmatter":{"type":"decision","scope":"work","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["帮老适","AI转型","技术路线","框架v2","决策"]},"headers":[],"relativePath":"vault/Memory/Decisions/帮老适-AI转型框架v2迭代决策.md","filePath":"vault/Memory/Decisions/帮老适-AI转型框架v2迭代决策.md","lastUpdated":1789374053000}'),g={name:"vault/Memory/Decisions/帮老适-AI转型框架v2迭代决策.md"};function c(m,a,b,q,v,f){const r=l("VPNolebaseInlineLinkPreview"),n=l("NolebaseGitContributors"),s=l("NolebaseGitChangelog");return d(),h("div",null,[a[5]||(a[5]=_('<h1 id="帮老适-ai-转型框架-v2-迭代决策-2026-09-12" tabindex="-1">帮老适 AI 转型框架 v2 迭代决策（2026-09-12） <a class="header-anchor" href="#帮老适-ai-转型框架-v2-迭代决策-2026-09-12" aria-label="Permalink to “帮老适 AI 转型框架 v2 迭代决策（2026-09-12）”">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>框架 v1 存在与执行现实脱节的问题：技术路线写&quot;扣子/影刀&quot;，但客服主线实际已跑在店小蜜/百炼；框架号称转型框架但只覆盖电商线；同行案例检索（5 路独立检索、约 40 个案例）产出的大量修正输入未回写。经评审后对框架做整体 v2 迭代。</p><h2 id="决策与理由" tabindex="-1">决策与理由 <a class="header-anchor" href="#决策与理由" aria-label="Permalink to “决策与理由”">​</a></h2><h3 id="_1-技术路线-扣子-→-店小蜜-5-0-百炼-为主力" tabindex="-1">1. 技术路线：扣子 → 店小蜜 5.0 / 百炼 为主力 <a class="header-anchor" href="#_1-技术路线-扣子-→-店小蜜-5-0-百炼-为主力" aria-label="Permalink to “1. 技术路线：扣子 → 店小蜜 5.0 / 百炼 为主力”">​</a></h3><ul><li><strong>选择</strong>：对客通道与托管 RAG 用店小蜜 5.0 / 百炼（阿里官方）；开源 RAG（RAGFlow/Dify）降为知识库实验与备份，不做主力。</li><li><strong>理由</strong>：① 实际执行已在店小蜜/百炼，文档必须与现实验证一致；② 语忆科技等同行均用百炼而非纯自建；③ 政企私有化案例显示 1 人团队纯自建开源 RAG 全栈风险高；④ &quot;不采购商业系统&quot;红线下扣子（公有云 SaaS）也站不住。</li></ul><h3 id="_2-框架定位收窄为《电商链路试点框架》" tabindex="-1">2. 框架定位收窄为《电商链路试点框架》 <a class="header-anchor" href="#_2-框架定位收窄为《电商链路试点框架》" aria-label="Permalink to “2. 框架定位收窄为《电商链路试点框架》”">​</a></h3><ul><li><strong>选择</strong>：封面/第 2 节/第 8 节明确边界声明——本框架只覆盖营收 55-65% 的电商线 0-3 个月试点；删除所有对《执行方案》的引用（执行方案不应干扰框架独立性）。</li><li><strong>理由</strong>：只覆盖电商却号称公司级是名不副实；框架应自洽，不预判后续文档。</li></ul><h3 id="_3-内容生成升级为-p0-战略并行主线-与客服并行" tabindex="-1">3. 内容生成升级为 P0 战略并行主线（与客服并行） <a class="header-anchor" href="#_3-内容生成升级为-p0-战略并行主线-与客服并行" aria-label="Permalink to “3. 内容生成升级为 P0 战略并行主线（与客服并行）”">​</a></h3><ul><li><strong>选择</strong>：双 P0——客服（开发负责）+ 内容生成（管培生 + 温总内容输入 + API，不占开发资源），M1 即双线启动。</li><li><strong>理由</strong>：内容生成直击头号痛点&quot;市场教育难&quot;；品牌资产（温总叙事/微光手册/品牌故事）已高度结构化，数据就绪度接近满格，是同行抄不走的护城河；两线资源不冲突。</li></ul><h3 id="_4-公司级-8-项-ai-需求不并入试点框架" tabindex="-1">4. 公司级 8 项 AI 需求不并入试点框架 <a class="header-anchor" href="#_4-公司级-8-项-ai-需求不并入试点框架" aria-label="Permalink to “4. 公司级 8 项 AI 需求不并入试点框架”">​</a></h3><ul><li><strong>选择</strong>：8 项需求（含工程询价、设计辅助、ERP 提效、GEO、音频评估、经销商知识库等 6 项范围外）只在会上口头提&quot;已梳理、验证后规划&quot;，不写入框架主体。</li><li><strong>理由</strong>：并进来&quot;单点穿透&quot;原则当场作废；1+1 团队做 8 个项目每个都跑不通；会议焦点会散。</li></ul><h3 id="_5-平台原生工具优先" tabindex="-1">5. 平台原生工具优先 <a class="header-anchor" href="#_5-平台原生工具优先" aria-label="Permalink to “5. 平台原生工具优先”">​</a></h3><ul><li><strong>选择</strong>：新增&quot;平台红利&quot;约束行 + 原则卡 + 天猫原生工具盘点表（家作棚拍/万相台/货品全站推/生意管家/智能预警/数字人直播）。</li><li><strong>理由</strong>：6 个工具零成本、官方背书、1 人团队即可启用；芝华仕实证 AI 图点击率超实拍 30-70%。这是小团队最高杠杆动作。</li></ul><h3 id="_6-脱敏从-人工执行-改为-技术层强制" tabindex="-1">6. 脱敏从&quot;人工执行&quot;改为&quot;技术层强制&quot; <a class="header-anchor" href="#_6-脱敏从-人工执行-改为-技术层强制" aria-label="Permalink to “6. 脱敏从&quot;人工执行&quot;改为&quot;技术层强制&quot;”">​</a></h3><ul><li><strong>选择</strong>：正则 + NER 实体识别前置清洗节点自动去标识化，人工仅做规则校验与抽审；v1&quot;管培生执行、负责人抽检&quot;方案废除。</li><li><strong>理由</strong>：6-12 个月客服聊天记录混有电话/地址/健康自述，人工脱敏漏检率必然存在，健康信息漏入公有云即隐私事件；合规不能靠自觉。</li></ul><h3 id="_7-适老行业专属硬规则-3-轮未解决即转人工" tabindex="-1">7. 适老行业专属硬规则：3 轮未解决即转人工 <a class="header-anchor" href="#_7-适老行业专属硬规则-3-轮未解决即转人工" aria-label="Permalink to “7. 适老行业专属硬规则：3 轮未解决即转人工”">​</a></h3><ul><li><strong>选择</strong>：客服 AI 补转人工硬规则 + 老年语义高敏感触发（&quot;找人工&quot;&quot;听不懂&quot;&quot;找人&quot;即转）；转人工率作反向指标监控而非一味压低。</li><li><strong>理由</strong>：79% 用户对 AI 客服沮丧、典型案例 40 分钟才转人工（江苏消保委）；老人对&quot;转不到人&quot;容忍度极低，这是适老行业最大雷区。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to “关联”">​</a></h2>',19)),e("ul",null,[e("li",null,[a[1]||(a[1]=t("项目概况：",-1)),o(r,{class:"route-link nolebase-route-link-invalid",href:"#",target:"_target"},{default:i(()=>[...a[0]||(a[0]=[t("_overview",-1)])]),_:1})]),e("li",null,[a[3]||(a[3]=t("文档体系分工：",-1)),o(r,{href:"/knowledge/vault/Memory/Decisions/帮老适-AI转型文档体系分工.html"},{default:i(()=>[...a[2]||(a[2]=[t("帮老适-AI转型文档体系分工",-1)])]),_:1})]),a[4]||(a[4]=e("li",null,[t("案例佐证："),e("code",null,"E:\\work\\projects\\AI-driven transformation\\同行AI化案例库_成功与踩坑.md")],-1))]),o(n),o(s)])}const I=u(g,[["render",c]]);export{P as __pageData,I as default};
